    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=5.0">
    <title>Heart Surgery in China | Cardiac Treatment Guide | Save 70-85%</title>
    <meta name="description" content="Get world-class heart surgery in China for 70-85% less than Western prices. Top-ranked cardiology at Fuwai Hospital, Shanghai Chest Hospital & more. CABG, valve replacement, angioplasty, TAVR. Free consultation.">
    <meta name="keywords" content="heart surgery China, cardiac treatment China, CABG China, bypass surgery China, valve replacement China, TAVR China, angioplasty China, Fuwai Hospital cardiology, best heart hospital China, cardiology Shanghai">
    <meta name="author" content="China Hospitals Guide">
    <meta name="robots" content="index, follow">
    <link rel="canonical" href="https://chinahospitalsguide.com/treatments/cardiac.html">

    <!-- Open Graph -->
    <meta property="og:title" content="Heart Surgery in China | Save 70-85% on Cardiac Treatment">
    <meta property="og:description" content="World-class cardiology at China's top hospitals. CABG, valve replacement, angioplasty & more at a fraction of Western prices.">
    <meta property="og:type" content="website">
    <meta property="og:url" content="https://chinahospitalsguide.com/treatments/cardiac.html">

    <!-- Styles -->
    <link rel="stylesheet" href="../styles.css">
    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>

    <!-- Google Analytics -->
    <script async src="https://www.googletagmanager.com/gtag/js?id=G-RVYZENK472"></script>
    <script>
        window.dataLayer = window.dataLayer || [];
        function gtag(){dataLayer.push(arguments);}
        gtag('js', new Date());
        gtag('config', 'G-RVYZENK472');
    </script>

    <style>
        /* Page-specific cardiac styles */
        .cardiac-hero {
            padding: 160px 0 100px;
            background: linear-gradient(135deg, rgba(12, 24, 48, 0.92), rgba(30, 60, 114, 0.88)),
                        url('../images/china-hospital.jpg') center/cover no-repeat;
            color: white;
            position: relative;
        }

        .cardiac-hero::after {
            content: '';
            position: absolute;
            bottom: 0;
            left: 0;
            right: 0;
            height: 120px;
            background: linear-gradient(to top, var(--bg), transparent);
        }

        .cardiac-hero .hero-inner {
            max-width: 1180px;
            margin: 0 auto;
            padding: 0 20px;
        }

        .hero-kicker {
            display: inline-block;
            margin-bottom: 18px;
            padding: 8px 18px;
            border-radius: 999px;
            border: 1px solid rgba(255,255,255,0.3);
            background: rgba(255,255,255,0.1);
            font-size: 0.82rem;
            text-transform: uppercase;
            letter-spacing: 0.08em;
            font-weight: 600;
        }

        .hero-kicker .heart-icon {
            display: inline-block;
            margin-right: 6px;
            animation: heartbeat 1.5s ease-in-out infinite;
        }

        @keyframes heartbeat {
            0%, 100% { transform: scale(1); }
            14% { transform: scale(1.15); }
            28% { transform: scale(1); }
            42% { transform: scale(1.15); }
            56% { transform: scale(1); }
        }

        .cardiac-hero h1 {
            font-size: clamp(2.2rem, 5vw, 3.8rem);
            line-height: 1.1;
            margin-bottom: 20px;
            color: white;
            font-family: 'Playfair Display', Georgia, serif;
        }

        .cardiac-hero .hero-subtitle {
            font-size: 1.15rem;
            color: rgba(255,255,255,0.88);
            max-width: 640px;
            margin-bottom: 28px;
            line-height: 1.7;
        }

        .hero-savings-badge {
            display: inline-flex;
            align-items: center;
            gap: 10px;
            background: linear-gradient(135deg, #e85d5d, #ff8e8e);
            color: white;
            padding: 12px 24px;
            border-radius: 50px;
            font-weight: 700;
            font-size: 1.1rem;
            margin-bottom: 24px;
            box-shadow: 0 8px 24px rgba(232, 93, 93, 0.35);
        }

        .hero-savings-badge .big-save {
            font-size: 1.4rem;
        }

        .hero-cta-row {
            display: flex;
            flex-wrap: wrap;
            gap: 16px;
            margin-bottom: 36px;
        }

        .cta-button {
            display: inline-flex;
            align-items: center;
            gap: 8px;
            padding: 14px 32px;
            background: #ff6b6b;
            color: white;
            border-radius: 30px;
            text-decoration: none;
            font-weight: 700;
            font-size: 1rem;
            transition: all 0.3s ease;
            box-shadow: 0 6px 20px rgba(255, 107, 107, 0.3);
        }

        .cta-button:hover {
            background: #ff5252;
            transform: translateY(-2px);
            box-shadow: 0 10px 28px rgba(255, 107, 107, 0.4);
        }

        .cta-button.secondary {
            background: rgba(255,255,255,0.15);
            border: 1px solid rgba(255,255,255,0.35);
            box-shadow: none;
        }

        .cta-button.secondary:hover {
            background: rgba(255,255,255,0.25);
        }

        .hero-quick-stats {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
            gap: 14px;
            max-width: 600px;
        }

        .quick-stat {
            background: rgba(255,255,255,0.08);
            border: 1px solid rgba(255,255,255,0.12);
            border-radius: 14px;
            padding: 16px 18px;
        }

        .quick-stat strong {
            display: block;
            font-size: 1.5rem;
            color: white;
            margin-bottom: 4px;
        }

        .quick-stat span {
            font-size: 0.82rem;
            color: rgba(255,255,255,0.7);
            text-transform: uppercase;
            letter-spacing: 0.05em;
        }

        /* Section styling */
        .section {
            padding: 80px 20px;
        }

        .section-light {
            background: var(--bg);
        }

        .section-white {
            background: white;
        }

        .section-dark {
            background: linear-gradient(135deg, #0f1f3d, #1a3a6b);
            color: white;
        }

        .section-inner {
            max-width: 1180px;
            margin: 0 auto;
        }

        .section-header {
            text-align: center;
            margin-bottom: 48px;
        }

        .section-header h2 {
            font-size: clamp(1.8rem, 3.5vw, 2.6rem);
            margin-bottom: 14px;
            color: var(--dark);
        }

        .section-dark .section-header h2 {
            color: white;
        }

        .section-header p {
            font-size: 1.05rem;
            color: var(--text-light);
            max-width: 620px;
            margin: 0 auto;
        }

        .section-dark .section-header p {
            color: rgba(255,255,255,0.75);
        }

        /* Why China Cards */
        .why-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
            gap: 24px;
        }

        .why-card {
            background: white;
            border-radius: 20px;
            padding: 32px 28px;
            box-shadow: var(--shadow);
            border: 1px solid rgba(30, 60, 114, 0.06);
            transition: transform 0.3s ease, box-shadow 0.3s ease;
        }

        .why-card:hover {
            transform: translateY(-4px);
            box-shadow: var(--shadow-lg);
        }

        .why-card .icon-circle {
            width: 64px;
            height: 64px;
            border-radius: 50%;
            background: linear-gradient(135deg, rgba(30, 60, 114, 0.08), rgba(42, 82, 152, 0.12));
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 1.8rem;
            margin-bottom: 20px;
        }

        .why-card h3 {
            font-size: 1.2rem;
            margin-bottom: 10px;
            color: var(--dark);
            font-family: 'Playfair Display', Georgia, serif;
        }

        .why-card p {
            color: var(--text-light);
            font-size: 0.95rem;
            line-height: 1.65;
        }

        /* Procedure Cards */
        .procedure-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
            gap: 28px;
        }

        .procedure-card {
            background: white;
            border-radius: 20px;
            overflow: hidden;
            box-shadow: var(--shadow);
            border: 1px solid rgba(30, 60, 114, 0.06);
            transition: transform 0.3s ease, box-shadow 0.3s ease;
        }

        .procedure-card:hover {
            transform: translateY(-4px);
            box-shadow: var(--shadow-lg);
        }

        .procedure-header {
            background: linear-gradient(135deg, var(--primary), var(--secondary));
            color: white;
            padding: 24px 28px;
            position: relative;
        }

        .procedure-header .procedure-icon {
            font-size: 2.2rem;
            margin-bottom: 10px;
        }

        .procedure-header h3 {
            font-size: 1.25rem;
            color: white;
            margin-bottom: 4px;
            font-family: 'Playfair Display', Georgia, serif;
        }

        .procedure-header .procedure-tag {
            display: inline-block;
            padding: 4px 12px;
            background: rgba(255,255,255,0.2);
            border-radius: 20px;
            font-size: 0.75rem;
            text-transform: uppercase;
            letter-spacing: 0.05em;
            margin-top: 8px;
        }

